+    fn line_spans(&self, pane: PaneFocus, row: usize, line: &str) -> Spans<'static> {
+        let Some((start, end)) = self.selection_range_for_line(pane, row, line.chars().count())
+        else {
+            return Spans::from(vec![Span::raw(line.to_string())]);
