+    fn selection_pane(&self) -> Option<PaneFocus> {
+        self.visual_selection.as_ref().map(|selection| selection.pane)
+    }
+
+    fn selection_range_for_line(
+        &self,
+        pane: PaneFocus,
+        row: usize,
+        line_len: usize,
+    ) -> Option<(usize, usize)> {
+        let selection = self.visual_selection.as_ref()?;
+        if selection.pane != pane {
+            return None;
+        }
+        selection_range_for_line(selection, row, line_len)
+    }
