+    fn handle_visual_key(&mut self, key: UiKey) -> Option<Vec<UiAction>> {
+        self.visual_selection.as_ref()?;
+        match key {
+            UiKey::Esc => {
+                self.clear_visual_selection();
+                Some(Vec::new())
+            }
+            UiKey::Char('v') => {
+                self.clear_visual_selection();
+                Some(Vec::new())
+            }
+            UiKey::Char('V') => {
+                self.set_visual_mode(VisualMode::Line);
+                Some(Vec::new())
+            }
+            UiKey::Char(ch) if ch == CTRL_V => {
+                self.set_visual_mode(VisualMode::Block);
+                Some(Vec::new())
+            }
+            UiKey::Char('y') => {
+                self.yank_visual_selection(false);
+                Some(Vec::new())
+            }
+            UiKey::Char('Y') => {
+                self.yank_visual_selection(true);
+                Some(Vec::new())
+            }
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_selection(0, -1);
+                Some(Vec::new())
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_selection(1, 0);
+                Some(Vec::new())
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_selection(-1, 0);
+                Some(Vec::new())
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_selection(0, 1);
+                Some(Vec::new())
+            }
+            _ => Some(Vec::new()),
+        }
+    }
+
+    fn start_visual_selection(&mut self, mode: VisualMode) {
+        let pane = self.focus;
+        let lines = self.visual_lines(pane);
+        if lines.is_empty() {
+            return;
+        }
+        let mut position = self.visual_start_position(pane, &lines);
+        if mode == VisualMode::Line {
+            position.column = 0;
+        }
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            mode,
+            anchor: position,
+            cursor: position,
+        });
+    }
+
+    fn set_visual_mode(&mut self, mode: VisualMode) {
+        if let Some(selection) = &mut self.visual_selection {
+            selection.mode = mode;
+            if mode == VisualMode::Line {
+                selection.anchor.column = 0;
+                selection.cursor.column = 0;
+            }
+        }
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn visual_lines(&self, pane: PaneFocus) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => self
+                .left_pane_rows()
+                .into_iter()
+                .map(|row| row.text)
+                .collect(),
+            PaneFocus::Right => self.last_right_lines.borrow().clone(),
+        }
+    }
+
+    fn visual_start_position(&self, pane: PaneFocus, lines: &[String]) -> TextPosition {
+        match pane {
+            PaneFocus::Left => clamp_position(
+                TextPosition {
+                    row: self.control_selected,
+                    column: 0,
+                },
+                lines,
+            ),
+            PaneFocus::Right => clamp_position(self.last_right_cursor.get(), lines),
+        }
+    }
+
+    fn move_visual_selection(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.visual_lines(selection.pane);
+        let cursor = move_position(selection.cursor, row_delta, column_delta, &lines);
+        self.visual_selection = Some(VisualSelection {
+            cursor,
+            ..selection
+        });
+    }
+
+    fn yank_visual_selection(&mut self, force_linewise: bool) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.visual_lines(selection.pane);
+        let text = selected_text(&lines, selection, force_linewise);
+        self.copy_text(text);
+        self.clear_visual_selection();
+    }
+
+    fn yank_current_line(&mut self) {
+        let lines = self.visual_lines(self.focus);
+        if lines.is_empty() {
+            return;
+        }
+        let position = self.visual_start_position(self.focus, &lines);
+        if let Some(line) = lines.get(position.row) {
+            self.copy_text(line.clone());
+        }
+    }
+
+    fn copy_text(&mut self, text: String) {
+        let char_count = text.chars().count();
+        self.yank_buffer = Some(text.clone());
+        self.pending_clipboard.replace(Some(text));
+        self.show_status_notice(
+            format!("copied {char_count} chars"),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn cache_right_view(&self, right_content: &str, cursor_column: Option<usize>) {
+        let lines = split_lines_preserving_empty(right_content);
+        let row = lines.len().saturating_sub(1);
+        let column = cursor_column.unwrap_or_else(|| {
+            lines
+                .last()
+                .map(|line| line.chars().count())
+                .unwrap_or_default()
+        });
+        self.last_right_cursor
+            .set(clamp_position(TextPosition { row, column }, &lines));
+        self.last_right_lines.replace(lines);
+    }
+
+    fn visual_cursor_screen_position(&self) -> Option<(u16, u16)> {
+        let selection = self.visual_selection.as_ref()?;
+        let layout = self.layout();
+        match selection.pane {
+            PaneFocus::Left if self.left_visible => Some((
+                2_u16.saturating_add(selection.cursor.row.min(usize::from(u16::MAX)) as u16),
+                2_u16.saturating_add(selection.cursor.column.min(usize::from(u16::MAX)) as u16),
+            )),
+            PaneFocus::Right => Some((
+                2_u16.saturating_add(selection.cursor.row.min(usize::from(u16::MAX)) as u16),
+                layout
+                    .left_width
+                    .saturating_add(2)
+                    .saturating_add(selection.cursor.column.min(usize::from(u16::MAX)) as u16),
+            )),
+            PaneFocus::Left => None,
+        }
+    }
