+fn styled_range_spans(line: &str, start: usize, end: usize) -> Spans<'static> {
+    let line_len = line.chars().count();
+    let start = start.min(line_len);
+    let end = end.min(line_len);
+    if start >= end {
+        return Spans::from(vec![Span::raw(line.to_string())]);
+    }
+
+    let start_byte = byte_index_for_char(line, start);
+    let end_byte = byte_index_for_char(line, end);
+    let mut spans = Vec::new();
+    if start_byte > 0 {
+        spans.push(Span::raw(line[..start_byte].to_string()));
+    }
+    spans.push(Span::styled(
+        line[start_byte..end_byte].to_string(),
+        Style::default().add_modifier(Modifier::REVERSED),
+    ));
+    if end_byte < line.len() {
+        spans.push(Span::raw(line[end_byte..].to_string()));
+    }
+    Spans::from(spans)
+}
+
+fn byte_index_for_char(text: &str, char_index: usize) -> usize {
+    text.char_indices()
+        .nth(char_index)
+        .map(|(index, _)| index)
+        .unwrap_or(text.len())
+}
+
+fn split_lines_preserving_empty(content: &str) -> Vec<String> {
+    if content.is_empty() {
+        return vec![String::new()];
+    }
+    content.split('\n').map(str::to_string).collect()
+}
+
+fn clamp_position(position: TextPosition, lines: &[String]) -> TextPosition {
+    if lines.is_empty() {
+        return TextPosition { row: 0, column: 0 };
+    }
+    let row = position.row.min(lines.len() - 1);
+    let line_len = lines[row].chars().count();
+    TextPosition {
+        row,
+        column: position.column.min(line_len.saturating_sub(1)),
+    }
+}
+
+fn move_position(
+    position: TextPosition,
+    row_delta: isize,
+    column_delta: isize,
+    lines: &[String],
+) -> TextPosition {
+    if lines.is_empty() {
+        return TextPosition { row: 0, column: 0 };
+    }
+    let row = offset_index(position.row, row_delta, lines.len() - 1);
+    let line_len = lines[row].chars().count();
+    let column = offset_index(position.column, column_delta, line_len.saturating_sub(1));
+    TextPosition { row, column }
+}
+
+fn offset_index(current: usize, delta: isize, max: usize) -> usize {
+    if delta < 0 {
+        current.saturating_sub(delta.unsigned_abs()).min(max)
+    } else {
+        current.saturating_add(delta as usize).min(max)
+    }
+}
+
+fn ordered_positions(left: TextPosition, right: TextPosition) -> (TextPosition, TextPosition) {
+    if (left.row, left.column) <= (right.row, right.column) {
+        (left, right)
+    } else {
+        (right, left)
+    }
+}
+
+fn selection_range_for_line(
+    selection: &VisualSelection,
+    row: usize,
+    line_len: usize,
+) -> Option<(usize, usize)> {
+    match selection.mode {
+        VisualMode::Character => character_selection_range(selection, row, line_len),
+        VisualMode::Line => line_selection_range(selection, row, line_len),
+        VisualMode::Block => block_selection_range(selection, row, line_len),
+    }
+}
+
+fn character_selection_range(
+    selection: &VisualSelection,
+    row: usize,
+    line_len: usize,
+) -> Option<(usize, usize)> {
+    if line_len == 0 {
+        return None;
+    }
+    let (start, end) = ordered_positions(selection.anchor, selection.cursor);
+    if row < start.row || row > end.row {
+        return None;
+    }
+    if start.row == end.row {
+        return inclusive_range(start.column, end.column, line_len);
+    }
+    if row == start.row {
+        return Some((start.column.min(line_len - 1), line_len));
+    }
+    if row == end.row {
+        return Some((0, end.column.min(line_len - 1) + 1));
+    }
+    Some((0, line_len))
+}
+
+fn line_selection_range(
+    selection: &VisualSelection,
+    row: usize,
+    line_len: usize,
+) -> Option<(usize, usize)> {
+    let start = selection.anchor.row.min(selection.cursor.row);
+    let end = selection.anchor.row.max(selection.cursor.row);
+    (start..=end)
+        .contains(&row)
+        .then_some((0, line_len))
+        .filter(|(start, end)| start < end)
+}
+
+fn block_selection_range(
+    selection: &VisualSelection,
+    row: usize,
+    line_len: usize,
+) -> Option<(usize, usize)> {
+    if line_len == 0 {
+        return None;
+    }
+    let start_row = selection.anchor.row.min(selection.cursor.row);
+    let end_row = selection.anchor.row.max(selection.cursor.row);
+    if row < start_row || row > end_row {
+        return None;
+    }
+    let start_column = selection.anchor.column.min(selection.cursor.column);
+    let end_column = selection.anchor.column.max(selection.cursor.column);
+    if start_column >= line_len {
+        return None;
+    }
+    Some((start_column, (end_column + 1).min(line_len)))
+}
+
+fn inclusive_range(start: usize, end: usize, line_len: usize) -> Option<(usize, usize)> {
+    if line_len == 0 {
+        return None;
+    }
+    let start = start.min(line_len - 1);
+    let end = end.min(line_len - 1);
+    (start <= end).then_some((start, end + 1))
+}
+
+fn selected_text(lines: &[String], selection: VisualSelection, force_linewise: bool) -> String {
+    let mode = if force_linewise {
+        VisualMode::Line
+    } else {
+        selection.mode
+    };
+    let selection = VisualSelection { mode, ..selection };
+    lines
+        .iter()
+        .enumerate()
+        .filter_map(|(row, line)| {
+            selection_range_for_line(&selection, row, line.chars().count())
+                .map(|(start, end)| text_char_range(line, start, end))
+        })
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn text_char_range(text: &str, start: usize, end: usize) -> String {
+    let start_byte = byte_index_for_char(text, start);
+    let end_byte = byte_index_for_char(text, end);
+    text[start_byte..end_byte].to_string()
+}
+
+fn osc52_clipboard_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::new();
+    for chunk in bytes.chunks(3) {
+        let first = chunk[0];
+        let second = *chunk.get(1).unwrap_or(&0);
+        let third = *chunk.get(2).unwrap_or(&0);
+        encoded.push(TABLE[(first >> 2) as usize] as char);
+        encoded.push(TABLE[(((first & 0b0000_0011) << 4) | (second >> 4)) as usize] as char);
+        if chunk.len() > 1 {
+            encoded.push(TABLE[(((second & 0b0000_1111) << 2) | (third >> 6)) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+        if chunk.len() > 2 {
+            encoded.push(TABLE[(third & 0b0011_1111) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+    }
+    encoded
+}

